const event = $input.first().json;
const saleId = String(event.sale_id ?? event.id ?? '').trim();
if (!saleId) throw new Error('Gumroad ping rejected: sale_id is missing. No Airtable write was made.');
return [{ json: { saleId } }];

const response = $input.first().json;
const ping = $('Gumroad Trigger').first().json;
const requestedId = String(ping.sale_id ?? ping.id ?? '').trim();
const sale = response.sale ?? response.purchase ?? response.data?.sale ?? response.data ?? null;
if (response.success !== true || !sale || typeof sale !== 'object') throw new Error('Gumroad API did not confirm this sale. No Airtable write was made.');
const returnedIds = [sale.id, sale.sale_id].map(value => String(value ?? '').trim()).filter(Boolean);
if (!requestedId || !returnedIds.includes(requestedId)) throw new Error('The sale ID from the ping did not match the authenticated Gumroad API response. No Airtable write was made.');
if (sale.refunded === true || sale.disputed === true || sale.chargedback === true || sale.chargebacked === true) throw new Error('This sale is refunded or disputed and was not written by this sales-only workflow.');
const text = value => String(value ?? '').trim();
const orderNumber = text(sale.order_id ?? sale.order_number);
const email = text(sale.purchase_email ?? sale.email);
const productId = text(sale.product_id);
const currency = text(sale.currency).toUpperCase();
const priceMinor = Number(sale.price);
const saleDate = text(sale.sale_timestamp ?? sale.created_at);
const errors = [];
if (!orderNumber) errors.push('Missing order number');
if (!email.includes('@')) errors.push('Missing or invalid buyer email');
if (!productId) errors.push('Missing product ID');
if (!currency) errors.push('Missing currency');
if (!Number.isSafeInteger(priceMinor) || priceMinor < 0) errors.push('Invalid sale price');
if (!saleDate || Number.isNaN(Date.parse(saleDate))) errors.push('Missing or invalid sale date');
let amount;
if (currency) {
  try {
    const fractionDigits = new Intl.NumberFormat('en-US', { style: 'currency', currency }).resolvedOptions().maximumFractionDigits;
    amount = priceMinor / (10 ** fractionDigits);
  } catch { errors.push('Invalid currency code'); }
}
if (errors.length) throw new Error(`Verified sale rejected before Airtable write: ${errors.join('; ')}`);
const fields = {
  'Order Number': orderNumber,
  'Sale ID': text(sale.id ?? sale.sale_id),
  'Buyer Email': email,
  'Product ID': productId,
  'Product Name': text(sale.product_name),
  'Sale Amount': amount,
  'Currency': currency.toLowerCase(),
  'Sale Date': saleDate,
  'Can Contact': sale.can_contact === true
};
return [{ json: { requestBody: { performUpsert: { fieldsToMergeOn: ['Order Number'] }, records: [{ fields }] } } }];
